WITH flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_burst FROM sessions), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT s.id, s.customer_id, s.device, s.browser, s.started_at, s.country, s.is_new_burst, s.island_id, (SELECT MAX(t2.balance) FROM accounts t2 WHERE t2.customer_id = s.customer_id) AS max_account_balance FROM sessionized s ORDER BY started_at DESC NULLS LAST, customer_id DESC
